const logs = ["warn", "err", "warn", "info", "err"];
const buckets = Object.groupBy(logs, (x) => x);
const totals = Object.fromEntries(
  Object.entries(buckets).map(([k, list]) => [k, list.length]),
);

console.log(totals.warn, totals.err, totals.info);
console.log(Object.getPrototypeOf(buckets));
console.log(Object.getPrototypeOf(totals) === Object.prototype);
